"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[46640],{52076:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>i,contentTitle:()=>o,default:()=>c,frontMatter:()=>a,metadata:()=>r,toc:()=>d});var n=h(31085),s=h(71184);const a={sidebar_position:13,slug:"/bible/Matthew/Matthew_13",title:"Matthew 13",hide_table_of_contents:!0},o="Matthew",r={id:"bible/Matthew/Matthew 13",title:"Matthew 13",description:"Chapter 13",source:"@site/docs/bible/Matthew/Matthew 13.md",sourceDirName:"bible/Matthew",slug:"/bible/Matthew/Matthew_13",permalink:"/bibleNotes/docs/bible/Matthew/Matthew_13",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Matthew/Matthew 13.md",tags:[],version:"current",sidebarPosition:13,frontMatter:{sidebar_position:13,slug:"/bible/Matthew/Matthew_13",title:"Matthew 13",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Matthew 12",permalink:"/bibleNotes/docs/bible/Matthew/Matthew_12"},next:{title:"Matthew 14",permalink:"/bibleNotes/docs/bible/Matthew/Matthew_14"}},i={},d=[{value:"Chapter 13",id:"chapter-13",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h1,{id:"matthew",children:"Matthew"}),"\n",(0,n.jsx)(t.h2,{id:"chapter-13",children:"Chapter 13"}),"\n",(0,n.jsx)(t.p,{children:"The parables of the sower and the cockle:  of the mustardseed, etc."}),"\n",(0,n.jsx)(h,{verse:1,children:"The same day Jesus going out of the house, sat by the sea side."}),"\n",(0,n.jsx)(h,{verse:2,children:"And great multitudes were gathered together unto him, so that he went up into a boat and sat: and all the multitude stood on the shore."}),"\n",(0,n.jsx)(h,{verse:3,children:"And he spoke to them many things in parables, saying: Behold the sower went forth to sow."}),"\n",(0,n.jsx)(h,{verse:4,children:"And whilst he soweth some fell by the way side, and the birds of the air came and ate them up."}),"\n",(0,n.jsx)(h,{verse:5,children:"And other some fell upon stony ground, where they had not much earth: and they sprung up immediately, because they had no deepness of earth."}),"\n",(0,n.jsx)(h,{verse:6,children:"And when the sun was up they were scorched: and because they had not root, they withered away."}),"\n",(0,n.jsx)(h,{verse:7,children:"And others fell among thorns: and the thorns grew up and choked them."}),"\n",(0,n.jsx)(h,{verse:8,children:"And others fell upon good ground: and they brought forth fruit, some an hundred fold, some sixty fold, and some thirty fold."}),"\n",(0,n.jsx)(h,{verse:9,children:"He that hath ears to hear, let him hear."}),"\n",(0,n.jsx)(h,{verse:10,children:"And his disciples came and said to him: Why speakest thou to them in parables?"}),"\n",(0,n.jsx)(h,{verse:11,children:"Who answered and said to them: Because to you it is given to know the mysteries of the kingdom of heaven: but to them it is not given."}),"\n",(0,n.jsx)(h,{verse:12,children:"For he that hath, to him shall be given, and he shall abound: but he that hath not, from him shall be taken away that also which he hath."}),"\n",(0,n.jsx)(h,{verse:13,children:"Therefore do I speak to them in parables: because seeing they see not, and hearing they hear not, neither do they understand."}),"\n",(0,n.jsx)(h,{verse:14,children:"And the prophecy of Isaias is fulfilled in them, who saith: By hearing you shall hear, and shall not understand: and seeing you shall see, and shall not perceive."}),"\n",(0,n.jsx)(h,{verse:15,children:"For the heart of this people is grown gross, and with their ears they have been dull of hearing, and their eyes they have shut: lest at any time they should see with their eyes, and hear with their ears, and understand with their heart, and be converted, and I should heal them."}),"\n",(0,n.jsx)(h,{verse:16,children:"But blessed are your eyes, because they see, and your ears, because they hear."}),"\n",(0,n.jsx)(h,{verse:17,children:"For, amen, I say to you, many prophets and just men have desired to see the things that you see, and have not seen them: and to hear the things that you hear and have not heard them."}),"\n",(0,n.jsx)(h,{verse:18,children:"Hear you therefore the parable of the sower."}),"\n",(0,n.jsx)(h,{verse:19,children:"When any one heareth the word of the kingdom, and understandeth it not, there cometh the wicked one, and catcheth away that which was sown in his heart: this is he that received the seed by the way side."}),"\n",(0,n.jsx)(h,{verse:20,children:"And he that received the seed upon stony ground, is he that heareth the word, and immediately receiveth it with joy."}),"\n",(0,n.jsx)(h,{verse:21,children:"Yet hath he not root in himself, but is only for a time: and when there ariseth tribulation and persecution because of the word, he is presently scandalized."}),"\n",(0,n.jsx)(h,{verse:22,children:"And he that received the seed among thorns, is he that heareth the word, and the care of this world and the deceitfulness of riches choketh up the word, and he becometh fruitless."}),"\n",(0,n.jsx)(h,{verse:23,children:"But he that received the seed upon good ground, is he that heareth the word, and understandeth, and beareth fruit, and yieldeth the one an hundredfold, and another sixty, and another thirty."}),"\n",(0,n.jsx)(h,{verse:24,children:"Another parable he proposed to them, saying: The kingdom of heaven is likened to a man that sowed good seed in his field."}),"\n",(0,n.jsx)(h,{verse:25,children:"But while men were asleep, his enemy came and oversowed cockle among the wheat and went his way."}),"\n",(0,n.jsx)(h,{verse:26,children:"And when the blade was sprung up, and had brought forth fruit, then appeared also the cockle."}),"\n",(0,n.jsx)(h,{verse:27,children:"And the servants of the good man of the house coming said to him. Sir, didst thou not sow good seed in thy field? Whence then hath it cockle?"}),"\n",(0,n.jsx)(h,{verse:28,children:"And he said to them: An enemy hath done this. And the servants said to him: Wilt thou that we go and gather it up?"}),"\n",(0,n.jsx)(h,{verse:29,children:"And he said: No, lest perhaps gathering up the cockle, you root up the wheat also together with it."}),"\n",(0,n.jsx)(h,{verse:30,children:"Suffer both to grow until the harvest, and in the time of the harvest I will say to the reapers: Gather up first the cockle, and bind it into bundles to burn, but the wheat gather ye into my barn."}),"\n",(0,n.jsx)(h,{verse:31,children:"Another parable he proposed unto them, saying: The kingdom of heaven is like to a grain of mustard seed, which a man took and sowed in his field."}),"\n",(0,n.jsx)(h,{verse:32,children:"Which is the least indeed of all seeds; but when it is grown up, it is greater than all herbs, and becometh a tree, so that the birds of the air come, and dwell in the branches thereof."}),"\n",(0,n.jsx)(h,{verse:33,children:"Another parable he spoke to them: The kingdom of heaven is like to leaven, which a woman took and hid in three measures of meal, until the whole was leavened."}),"\n",(0,n.jsx)(h,{verse:34,children:"All these things Jesus spoke in parables to the multitudes: and without parables he did not speak to them."}),"\n",(0,n.jsx)(h,{verse:35,children:"That it might be fulfilled which was spoken by the prophet, saying: I will open my mouth in parables, I will utter things hidden from the foundation of the world."}),"\n",(0,n.jsx)(h,{verse:36,children:"Then having sent away the multitudes, he came into the house, and his disciples came to him, saying: Expound to us the parable of the cockle of the field."}),"\n",(0,n.jsx)(h,{verse:37,children:"Who made answer and said to them: He that soweth the good seed is the Son of man."}),"\n",(0,n.jsx)(h,{verse:38,children:"And the field is the world. And the good seed are the children of the kingdom. And the cockle are the children of the wicked one."}),"\n",(0,n.jsx)(h,{verse:39,children:"And the enemy that sowed them, is the devil. But the harvest is the end of the world. And the reapers are the angels."}),"\n",(0,n.jsx)(h,{verse:40,children:"Even as cockle therefore is gathered up, and burnt with fire: so shall it be at the end of the world."}),"\n",(0,n.jsx)(h,{verse:41,children:"The Son of man shall send his angels, and they shall gather out of his kingdom all scandals, and them that work iniquity."}),"\n",(0,n.jsx)(h,{verse:42,children:"And shall cast them into the furnace of fire: there shall be weeping and gnashing of teeth."}),"\n",(0,n.jsx)(h,{verse:43,children:"Then shall the just shine as the sun, in the kingdom of their Father. He that hath ears to hear, let him hear."}),"\n",(0,n.jsx)(h,{verse:44,children:"The kingdom of heaven is like unto a treasure hidden in a field. Which a man having found, hid it, and for joy thereof goeth, and selleth all that he hath, and buyeth that field."}),"\n",(0,n.jsx)(h,{verse:45,children:"Again the kingdom of heaven is like to a merchant seeking good pearls."}),"\n",(0,n.jsx)(h,{verse:46,children:"Who when he had found one pearl of great price, went his way, and sold all that he had, and bought it."}),"\n",(0,n.jsx)(h,{verse:47,children:"Again the kingdom of heaven is like to a net cast into the sea, and gathering together of all kinds of fishes."}),"\n",(0,n.jsx)(h,{verse:48,children:"Which, when it was filled, they drew out, and sitting by the shore, they chose out the good into vessels, but the bad they cast forth."}),"\n",(0,n.jsx)(h,{verse:49,children:"So shall it be at the end of the world. The angels shall go out, and shall separate the wicked from among the just."}),"\n",(0,n.jsx)(h,{verse:50,children:"And shall cast them into the furnace of fire: there shall be weeping and gnashing of teeth."}),"\n",(0,n.jsx)(h,{verse:51,children:"Have ye understood all these things? They say to him: Yes."}),"\n",(0,n.jsx)(h,{verse:52,children:"He said unto them: Therefore every scribe instructed in the kingdom of heaven, is like to a man that is a householder, who bringeth forth out of his treasure new things and old."}),"\n",(0,n.jsx)(h,{verse:53,children:"And it came to pass: when Jesus had finished these parables, he passed from thence."}),"\n",(0,n.jsx)(h,{verse:54,children:"And coming into his own country, he taught them in their synagogues, so that they wondered and said: How came this man by this wisdom and miracles?"}),"\n",(0,n.jsx)(h,{verse:55,children:"Is not this the carpenter's son? Is not his mother called Mary, and his brethren James, and Joseph, and Simon, and Jude:"}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: His brethren...These were the children of Mary the wife of Cleophas, sister to our Blessed Lady, (St. Matt. 27. 56; St. John 19. 25,) and therefore, according to the usual style of the Scripture, they were called brethren, that is, near relations to our Saviour."})}),"\n",(0,n.jsx)(h,{verse:56,children:"And his sisters, are they not all with us? Whence therefore hath he all these things?"}),"\n",(0,n.jsx)(h,{verse:57,children:"And they were scandalized in his regard. But Jesus said to them: A prophet is not without honour, save in his own country, and in his own house."}),"\n",(0,n.jsx)(h,{verse:58,children:"And he wrought not many miracles there, because of their unbelief."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>o,x:()=>r});var n=h(14041);const s={},a=n.createContext(s);function o(e){const t=n.useContext(a);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);